def calc(s):
 sales=297247.;fees=5907.;pv=0;rows=[]
 for year in range(1,11):
  old=sales;f=max(0,(year-5)/5);g=s['sales_growth'][year-1] if year<=5 else s['sales_growth'][-1]*(1-f)+s['g']*f;fg=s['fee_growth'][year-1] if year<=5 else s['fee_growth'][-1]*(1-f)+s['g']*f;sales*=1+g;fees*=1+fg;m=s['merch_margin'][year-1] if year<=5 else s['merch_margin'][-1]*(1-f)+s['terminal_merch_margin']*f;rev=sales+fees
  # Fee-related operating expenses remain in consolidated merchandise/SG&A margin. Fees not separately valued as pure cash profit.
  ebit=sales*m+fees;nopat=ebit*.745;da=sales*.009;maint=max(sales*s['maint'],297247*s['maint']*1.02**year);digital=sales*.002;growthcap=max(0,sales-old)*s['growth_capital'];capex=maint+digital+growthcap;nwc=(sales-old)*s['float_ratio'];explicit=capex-da+nwc;roic=s['roic']*(1-f)+s['terminal_roic']*f
  # Sales-growth funding cross-check; no extra capital charge for expensed productivity gains already retained in EBIT.
  return_floor=nopat*max(0,g)/roic;ri=max(explicit,return_floor);fcff=nopat-ri;pv+=fcff/(1+s['wacc'])**year
